<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">prog</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">context</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">context, </span><span style="color:#E06C75;font-style:italic;">question</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">question)</span></span>
